(()=>{'use strict';const root=document.getElementById('theoryLearner');root.innerHTML="<div class=\"app\" id=\"tl-app\"><header class=\"top\"><strong>♮ 乐理实验室</strong><nav aria-label=\"主导航\"><button data-page=\"home\">找知识 / 我忘了</button><button data-page=\"task\">我的练习片段</button><button data-page=\"evidence\">复习与记录</button></nav><span class=\"spacer\"></span><button id=\"tl-stop\">停止声音</button><button id=\"tl-midi\">连接MIDI</button><button id=\"tl-about\">说明</button></header><main id=\"tl-main\"></main><section class=\"dock hidden\" id=\"tl-dock\"><div class=\"dock-tools\"><span id=\"tl-input-label\">选音构造</span><span class=\"spacer\"></span><select id=\"tl-source\" aria-label=\"输入来源\"><option value=\"touch\">触屏</option><option value=\"midi\">MIDI</option></select><select id=\"tl-touch-mode\" aria-label=\"触屏模式\"><option value=\"latch\">点选保留</option><option value=\"hold\">多指按住</option></select><button id=\"tl-lower\">低八度</button><button id=\"tl-higher\">高八度</button><button id=\"tl-clear-notes\">清空选音</button><button id=\"tl-hide-keys\">收起键盘 ↓</button></div><div class=\"keys\" id=\"tl-keys\"></div><div id=\"tl-midi-state\" class=\"hidden\">等待设备输入</div></section></div><dialog id=\"tl-dialog\"><header><h2 id=\"tl-dialog-title\"></h2><button id=\"tl-close-dialog\">关闭 ×</button></header><div id=\"tl-dialog-body\"></div></dialog><div role=\"status\" class=\"toast hidden\" id=\"tl-toast\"></div>";
const C=ChordCore,K=LearnerCore,U=Curriculum,$=s=>root.querySelector(s),copy=K.clone;
const esc=s=>String(s??'').replace(/[&<>"']/g,x=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[x]));
const storage=TheoryData.adapter(PianoHost,'learner');const journal=new K.Journal(storage),player=new LearnerPlayer.Player(PianoAudio),defaultTask={kind:'interval',materialId:'A-Major-Melodic',tempo:60,hand:'both',bar:1,range:'all',pattern:'broken',notes:[],events:[],cursor:'第1小节第1拍'};
function validTask(t){return t&&['interval','chord','texture'].includes(t.kind)&&[40,60,80,100].includes(t.tempo)&&['both','left','right'].includes(t.hand)&&Number.isInteger(t.bar)&&t.bar>=1&&t.bar<=2&&Array.isArray(t.notes)}
if(!validTask(journal.data.task))journal.data.task=null;const savedSession=journal.data.session;if(savedSession&&(!savedSession.conceptId||!['question','support'].includes(savedSession.phase)||(savedSession.phase==='question'&&!savedSession.question?.kind)))journal.data.session=null;
const state={page:'home',query:'',category:'all',conceptId:'I02',lookupPurpose:'lookup',task:journal.data.task||copy(defaultTask),returnTask:journal.data.returnTask||null,session:journal.data.session||null,keyboardStart:48,keysHidden:innerWidth<650,quality:'major',pattern:'broken',duration:1,role:'auto',editorBar:'all',poolOptions:null,poolFamiliar:false,miniMinor:false};
const nav=journal.data.navigation;if(!state.session&&nav&&['home','concept','routes','task','evidence','pool'].includes(nav.page)){state.page=nav.page==='pool'?'home':nav.page;state.conceptId=LearnerContent.some(c=>c.id===nav.conceptId)?nav.conceptId:'I02';state.pattern=['block','broken','bass-chord'].includes(nav.pattern)?nav.pattern:'broken';state.demoId=nav.demoId;}
if(state.session){state.page='session';state.conceptId=state.session.conceptId;state.returnTask=state.session.returnTask||null;state.session.heard=false;state.session.playing=false;state.session.response=state.session.response||{notes:[],events:[]}}
let live=new Map(),pointerMap=new Map(),midiAccess=null,midiPorts=new Map(),midiStatus='未连接',toastTimer,debounceSearch,layoutTimer;
const input=new ChordInput.Input({delay:200,onStable(notes){if(state.page==='session'&&state.session?.phase==='question'){state.session.response.notes=[...notes];state.session.result=null;state.session.submitted=false;save();render()}else if(state.page==='task'){state.task.notes=[...notes];save();render()}},onChange(){updateKeys();$('#tl-midi-state').textContent=midiStatus+' · 持键 '+input.pitches().length+' · 踏板延音 '+input.sustained.size;},onSound(key,n,velocity){live.get(key)?.stop();live.set(key,PianoAudio.note(n,{duration:null,volume:velocity/190,release:.25}))},onRelease(key,immediate){const v=live.get(key);if(v){immediate?v.stop():v.release();live.delete(key)}}});
function concept(id=state.conceptId){return LearnerContent.find(c=>c.id===id)}
function material(id){return copy(LearnerMaterials.find(m=>m.id===id))}
function topic(id){return id.startsWith('I')?'音程':id.startsWith('C')?'和弦':'织体 / 伴奏'}
function practiceConcept(id){return id==='T01'?(state.pattern==='bass-chord'?'T03':'T02'):id}
function practiced(id){return U.practical.includes(id)}
function save(){journal.data.navigation={page:state.page,conceptId:state.conceptId,pattern:state.pattern,demoId:state.demoId||null};journal.data.returnTask=state.returnTask?copy(state.returnTask):null;journal.data.task=copy(state.task);journal.data.session=state.session?copy(state.session):null;journal.save()}
function stop(){player.stop();if(state.session){state.session.playing=false;save()}renderPlaying()}
function release(){pointerMap.clear();input.reset();for(const v of live.values())v.stop();live.clear()}
function quiet(){stop();release();if(state.session){state.session.heard=false;state.session.playing=false;save();}}
function toast(text){$('#tl-toast').textContent=text;$('#tl-toast').classList.remove('hidden');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#tl-toast').classList.add('hidden'),3100)}
function modal(title,html){quiet();$('#tl-dialog-title').textContent=title;$('#tl-dialog-body').innerHTML=html;if(!$('#tl-dialog').open)$('#tl-dialog').showModal()}
function closeModal(){$('#tl-dialog').close();syncLatch();updateKeys()}
function changePage(page){quiet();state.page=page;if(page==='task')exposeMaterial(taskMaterial(),'lookup',state.task.kind==='interval'?'I02':state.task.kind==='chord'?'C01':'T02');if(page!=='session'&&state.session){journal.event('leave-session',{sessionId:state.session.id});state.session=null}save();render()}
function duration(ms){if(ms===null||ms===undefined)return '尚无上次作答';if(ms<60000)return '不足1分钟';if(ms<86400000)return Math.floor(ms/3600000)+'小时'+Math.floor(ms%3600000/60000)+'分钟';return Math.floor(ms/86400000)+'天'+Math.floor(ms%86400000/3600000)+'小时'}
function returnLabel(){if(PianoHost.getDB().theory.returnContext)return '返回原曲原段';return state.returnTask?'返回片段 · 第'+state.returnTask.bar+'小节':'返回知识入口'}
function returnButton(){return `<button class="secondary return-button" data-action="return">${returnLabel()} ↗</button>`}
function openConcept(id,purpose='lookup'){quiet();if(state.page==='task')state.returnTask=copy(state.task);if(state.session){state.session.lookupSeen=true;save()}state.conceptId=id;state.demoId=null;state.lookupVariant=false;if(id==='T03')state.pattern='bass-chord';else if(id==='T02')state.pattern='broken';state.lookupPurpose=purpose;state.page=purpose==='recover'?'routes':'concept';if(purpose==='lookup')markLookup(id);save();render()}
function exposeMaterial(m,reason,id=state.conceptId){if(!m)return;for(const sig of U.materialSignatures(m))journal.expose(sig,reason,id)}
function markLookup(id){journal.event('lookup',{conceptId:id,purpose:'lookup',sourceTask:state.returnTask?.kind||null});exposeMaterial(mainExample(id),'lookup',id);if(state.session){state.session.lookupSeen=true;save()}}
function restoreTask(){quiet();if(PianoHost.getDB().theory.returnContext)return window.PianoTheory.returnSong();if(state.returnTask){state.task=copy(state.returnTask);state.returnTask=null;state.page='task';exposeMaterial(taskMaterial(),'lookup',state.task.kind==='interval'?'I02':state.task.kind==='chord'?'C01':'T02');journal.event('return-task',{task:state.task});}else state.page='home';state.session=null;save();render()}
function noteName(n,sp=null){return C.note(n,sp)}
function activeQuestion(){return state.session?.question}
function activeSpelling(){const q=activeQuestion();if(state.page==='session'&&q){if(q.spelling)return q.spelling;if(q.kind==='interval'){const sp=C.spell(q.root,C.byId('major'),q.rootLabel);const written=K.pitch(state.session.response.spelledUpper);if(written)sp[written.midi%12]={name:written.name.replace(/-?\d+$/,''),letter:written.letter,alter:written.alter};return sp}}return null}
function actualNotes(){return state.page==='session'?state.session?.response?.notes||[]:state.page==='task'?state.task.notes:[]}
function sequenceFromNotes(notes,beats=4){return LearnerPlayer.chord(notes,{beats})}
async function play(m,options={}){try{if(state.session)state.session.playing=true;renderPlaying();const ok=await player.play(m,{tempo:options.tempo||state.task.tempo||60,...options,onDone:()=>{if(state.session)state.session.playing=false;options.onDone?.();save();renderPlaying()}});if(!ok){if(state.session)state.session.playing=false;renderPlaying()}return ok}catch(e){if(state.session)state.session.playing=false;renderPlaying();toast('声音未启动或播放失败：'+e.message);return false}}
function renderPlaying(){root.querySelectorAll('[data-listen-status]').forEach(e=>{e.textContent=state.session?.playing?'正在播放，请听完这一组。':state.session?.heard?'已完整试听，可作答；重听次数 '+state.session.replays:'先完整试听一次，未播不记听辨证据。'})}
function staff(bottom,width=820){return Array.from({length:5},(_,i)=>`<line x1="30" x2="${width-25}" y1="${bottom-i*17}" y2="${bottom-i*17}" stroke="#95a1b0" stroke-width="1.05"/>`).join('')}
function writtenFor(n,sp){return sp?.[n%12]?C.note(n,sp):C.note(n)}
function point(n,written){const p=K.pitch(written)||K.pitch(C.note(n)),dia=p.octave*7+p.letter,treble=n>=60;return {y:(treble?132:270)-(dia-(treble?30:18))*8.5,bottom:treble?132:270,alter:p.alter}}
function notation(events,{bars=1,sp=null,title='',hideLabels=false}={}){const width=820,total=bars*4,trebleOnly=events.length&&events.every(e=>e.midi>=60);let svg=`<svg viewBox="${trebleOnly?'0 25 820 155':'0 25 820 285'}" role="img" aria-label="${esc(title||'实际音区与起拍谱面')}">${staff(132)}${trebleOnly?'':staff(270)}<path d="${PianoGlyphs.treble.path}" transform="translate(42 115) scale(.062 -.062)" fill="#111"/>${trebleOnly?'':'<path d="'+PianoGlyphs.bass.path+'" transform="translate(43 218) scale(.063 -.063)" fill="#111"/>'}`;for(let b=0;b<bars;b++){const x=112+b*(width-150)/bars;svg+=`<text x="${x}" y="43" class="notation-label">第${b+1}小节</text>`;if(b)svg+=`<line x1="${x-18}" x2="${x-18}" y1="64" y2="270" stroke="#a5b1c0"/>`}
 const rows=events.map((e,i)=>{const written=e.writtenPitch||writtenFor(e.midi,sp),p=point(e.midi,written),x=145+e.onsetBeat*(width-225)/total;let s='';if(p.y>p.bottom)for(let y=p.bottom+17;y<=p.y+1;y+=17)s+=`<line x1="${x-18}" x2="${x+18}" y1="${y}" y2="${y}" stroke="#111"/>`;if(p.y<p.bottom-68)for(let y=p.bottom-85;y>=p.y-1;y-=17)s+=`<line x1="${x-18}" x2="${x+18}" y1="${y}" y2="${y}" stroke="#111"/>`;s+=`<ellipse class="notation-note" cx="${x}" cy="${p.y}" rx="11" ry="7" transform="rotate(-16 ${x} ${p.y})" fill="${e.durationBeats>=2?'white':'#111'}" stroke="#111"/>`;if(e.durationBeats<4)s+=`<line x1="${x+10}" x2="${x+10}" y1="${p.y}" y2="${p.y-40}" stroke="#111" stroke-width="1.7"/>`;if(p.alter)s+=`<text x="${x-32}" y="${p.y+8}" font-family="Georgia" font-size="26" fill="#111">${p.alter>0?'♯'.repeat(p.alter):'♭'.repeat(-p.alter)}</text>`;if(!hideLabels)s+=`<text x="${x+20}" y="${p.y+5}" class="notation-label">${esc(written)}</text>`;return s});return svg+rows.join('')+'</svg>'}
function notesScore(notes,written=[],sp=null){return notation(notes.map((midi,i)=>({midi,writtenPitch:written[i]||null,onsetBeat:1.3,durationBeats:1})),{sp,hideLabels:notes.length>3})}
function home(){const query=state.query.trim().toLowerCase(),categories={all:'全部',I:'音程',C:'和弦',T:'织体 / 伴奏'};const list=LearnerContent.filter(c=>(state.category==='all'||c.id.startsWith(state.category))&&(!query||[c.title,...c.aliases,c['是什么']].join(' ').toLowerCase().includes(query)));const filtering=query||state.category!=='all';return `<div class="theory-home-grid"><section class="home-relation"><div class="eyebrow">从一个能听见的变化开始</div><h1>只改一个音，<br>为什么感觉就变了？</h1><p>用大小三和弦，把音程、命名和声音连起来。</p><div class="score">${notation([{midi:60,writtenPitch:'C4',onsetBeat:0,durationBeats:1},{midi:64,writtenPitch:'E4',onsetBeat:0,durationBeats:1},{midi:67,writtenPitch:'G4',onsetBeat:0,durationBeats:1},{midi:60,writtenPitch:'C4',onsetBeat:2,durationBeats:1},{midi:63,writtenPitch:'E♭4',onsetBeat:2,durationBeats:1},{midi:67,writtenPitch:'G4',onsetBeat:2,durationBeats:1}],{hideLabels:true})}</div><div class="home-change"><b>C → Cm</b><span>只改变三音 · E4 → E♭4</span></div><div class="actions"><button class="primary" data-concept="C01">理解这个关系</button><button class="secondary" data-action="forgot">我忘了，帮我找回</button></div></section><section class="home-knowledge"><div class="searchrow"><input id="tl-search" value="${esc(state.query)}" placeholder="查：大三度、C/E、G7、分解和弦" aria-label="搜索概念名或动作"></div><div class="pills">${Object.entries(categories).map(([id,label])=>`<button data-category="${id}" class="${state.category===id?'active':''}">${label}</button>`).join('')}</div>${filtering?'':`<button class="home-route" data-action="open-explorer"><strong>弹一下，看看是什么和弦</strong><span>结构、候选解释、下一步怎么接 ↗</span></button><button class="home-route" data-concept="T02"><strong>同样的和弦，换一种弹法</strong><span>柱式、分解与低音加和弦 ↗</span></button><button class="home-route" data-page="evidence"><strong>回顾我容易忘的关系</strong><span>命名、构造、听辨分别复习 ↗</span></button>`}<div class="library"><div class="concept-grid">${list.map(c=>`<button class="concept-card" data-concept="${c.id}"><header><strong>${c.title}</strong><span class="badge">${practiced(c.id)?'查阅＋实践':'查阅'}</span></header><p>${c['是什么']}</p></button>`).join('')||'<div class="empty">没有匹配项。可以搜音程、和弦或伴奏。</div>'}</div></div><small>${list.length}/18概念 · 按需要查阅，进阶范围如实标注。</small></section></div>`}

function simpleMaterial(notes,written,durations=null,onsets=null){return {bars:1,meter:[4,4],quarterNotesPerMinute:60,events:notes.map((midi,i)=>({midi,writtenPitch:written[i],onsetBeat:onsets?onsets[i]:0,durationBeats:durations?durations[i]:4,voice:'part'+i,hand:midi<60?'left':'right',velocity:68}))}}
function mainExample(id){if(state.demoId&&['concept','session'].includes(state.page)){const demo=material(state.demoId);if(demo)return demo}
const demos={I01:()=>simpleMaterial([64,65],['E4','F4'],[1,1],[0,1]),I03:()=>material('A-Major-Harmonic'),I04:()=>simpleMaterial([64,72],['E4','C5']),I05:()=>simpleMaterial([60,76],['C4','E5']),I06:()=>simpleMaterial([60,63],state.lookupVariant?['C4','D♯4']:['C4','E♭4']),C03:()=>simpleMaterial([48,55,64],['C3','G3','E4']),C04:()=>simpleMaterial(state.lookupVariant?[60,64,67,71]:[60,64,67,70],state.lookupVariant?['C4','E4','G4','B4']:['C4','E4','G4','B♭4']),C05:()=>material('B-Major'),C07:()=>simpleMaterial([59,62,65,69],['B3','D4','F4','A4']),T04:()=>{const m=U.textures('bass-chord')[0];m.events=m.events.map(e=>({...e,velocity:48}));for(const [midi,writtenPitch,onsetBeat]of [[76,'E5',0],[79,'G5',1],[76,'E5',2],[74,'D5',3],[77,'F5',4],[81,'A5',5],[79,'G5',6],[77,'F5',7]])m.events.push({midi,writtenPitch,onsetBeat,durationBeats:1,voice:'melody',hand:'right',role:'melody',velocity:76});return m},T05:()=>simpleMaterial([60,62,64,60],['C4','D4','E4','C4'],[1,1,1,1],[0,1,2,3])};
if(demos[id])return demos[id]();if(id==='I02')return material('A-Major-Melodic');if(id==='C02')return material('B-Inversion');if(id==='C06')return material('B-Flow');if(id.startsWith('T'))return U.textures(state.pattern)[0];if(id.startsWith('C'))return material('B-Major');return material('A-Major-Melodic')}
function conceptPage(){const c=concept(),m=mainExample(c.id);return `<div class="head"><div><div class="eyebrow">${topic(c.id)} · 直接查阅</div><h1>${c.title}</h1><p>立即看答案和原因。查阅不算考试，也不扣分。</p></div><span class="spacer"></span>${returnButton()}</div><div class="body-grid"><section class="panel"><div class="panel-head">${c.id==='C06'?'C大调背景 · G7 → C':c.id.startsWith('T')?'同一和声，时间组织可以不同':'先听、看或改变一个例子'}</div><div class="score">${notation(m.events,{bars:m.bars,hideLabels:m.events.length>6})}</div><div class="subline">${c['听到/看到/弹出什么']}</div><div class="support-controls" style="padding:0 14px 12px">${miniButtons(c.id)}</div></section><aside class="panel side"><div class="eyebrow">一句关系，再看证据</div><h2>${c['是什么']}</h2><p>${c['为何命名/形成']}</p><div class="rulebox">${c['控制变量对比']}</div><div class="details-area">${['常见误区','复习任务','迁移任务','可验收证据'].map(k=>`<details><summary>${k}</summary><p>${c[k]}</p></details>`).join('')}<details><summary>关联知识，按需回查</summary><p>${c.prerequisite}。这是回忆线索，不是进入本概念的门槛。</p><div class="inline-links">${(c.id.startsWith('I')?['I01','I02','I03','I06']:c.id.startsWith('C')?['I02','C01','C02','C06']:['C01','T01','T02','T03']).filter(id=>id!==c.id).map(id=>`<button class="secondary" data-concept="${id}">${concept(id).title}</button>`).join('')}</div></details></div></aside></div><div class="actions"><p>${practiced(c.id)?'实践、听辨与提示分别记录，不显示总掌握百分比。':'本单元已可查阅；进阶实践尚未实现，先按关联内容探索。'}</p>${c.id==='C01'?'<label class="controls">构造目标<select id="tl-quality"><option value="major" '+(state.quality==='major'?'selected':'')+'>大三和弦</option><option value="minor" '+(state.quality==='minor'?'selected':'')+'>小三和弦</option></select></label>':''}${practiced(c.id)?`<button class="secondary" data-action="recover">我忘了 / 定点恢复</button><button class="primary" data-action="practice">不看答案试一下 →</button>`:''}</div>`}
function miniButtons(id){if(['I01','I03','I04','I05','I06','C03','C04','C05','C07','T04','T05'].includes(id))return '<button class="secondary" data-action="play-lookup-example">▶ 听当前示例</button>'+(['I06','C04'].includes(id)?'<button class="secondary" data-action="lookup-variant">'+(id==='I06'?'切换E♭ / D♯谱写':'切换C7 / Cmaj7')+'</button>':'');if(id==='I02')return '<button class="secondary" data-demo="A-Major-Melodic">▶ 大三度</button><button class="secondary" data-demo="A-Minor-Melodic">▶ 小三度</button><button class="secondary" data-demo="A-Major-Harmonic">▶ 同时弹</button>';if(id==='C06')return '<button class="secondary" data-demo="B-Flow">▶ G7 → C</button><button class="secondary" data-action="flow-upper">▶ 只听两条线</button><button class="secondary" data-demo="B-Flow-WithoutF">▶ 去掉F比较</button><button class="secondary" data-demo="B-Alternative">▶ 另一走向Am</button>';if(id.startsWith('T'))return ['block','broken','bass-chord'].map(p=>`<button class="${state.pattern===p?'active':'secondary'}" data-pattern="${p}">▶ ${U.patternName(p)}</button>`).join('');if(id==='C02')return '<button class="secondary" data-demo="B-Root">▶ C原位</button><button class="secondary" data-demo="B-Inversion">▶ C/E</button>';if(id.startsWith('C'))return '<button class="secondary" data-demo="B-Major">▶ C大三</button><button class="secondary" data-demo="B-Minor">▶ Cm小三</button><button class="secondary" data-action="mini-change">把三音改一次</button>';return '<button class="secondary" data-demo="A-Major-Melodic">▶ 听例</button>'}
function routes(){const c=concept(),target=practiceConcept(c.id);return `<div class="head"><div><div class="eyebrow">${c.title} · 只恢复需要的部分</div><h1>这次，哪一部分想不起来？</h1><p>你的选择是自述，短测结果也只说明当前任务，不给人贴标签。</p></div><span class="spacer"></span>${returnButton()}</div><div class="controls"><label>恢复对象<select id="tl-recover-topic">${[['I02','音程：大/小三度'],['C01','和弦：大小三构成'],['C02','和弦：最低音与转位'],['C06','和弦：声部怎样接'],['T02','伴奏：柱式/逐拍分解'],['T03','伴奏：低音＋和弦']].map(([id,label])=>`<option value="${id}" ${state.conceptId===id?'selected':''}>${label}</option>`).join('')}</select></label><small>不知道术语时，按声音或动作选一个最接近的。</small></div><div class="body-grid"><section class="panel side"><h2>可以先试一下，也可以直接看最小提示</h2><p>忘名称、忘关系、听不出、找不到键、执行不顺，是不同情况。查阅模式仍可立即查看。</p><div class="route-list">${target==='I02'?`<button data-route="name"><b>忘了名字</b><small>给出谱写音程，恢复名称对应。</small></button><button data-route="relation"><b>关系记不清</b><small>音名字母位置与半音分别检查。</small></button><button data-route="construction"><b>想不起怎么构造</b><small>从给定下音找上方音。</small></button><button data-route="hearing"><b>会说，但听不出来</b><small>隐藏谱和键位，只凭声音判断。</small></button>`:target.startsWith('T')?'<button data-route="arrangement"><b>忘了拍位 / 音长</b><small>用实际时间编排检查，不按音级集合判断。</small></button><button data-action="skip-diagnosis"><b>知道难点，直接恢复</b><small>先分角色与四拍，再关闭提示换例。</small></button>':`<button data-route="${target==='C06'?'voice':'construction'}"><b>${target==='C02'?'最低音与转位记不清':target==='C06'?'声部怎样连接记不清':'组成音与三音记不清'}</b><small>先用当前音组检查，错误回到最小关系。</small></button><button data-action="skip-diagnosis"><b>不做短测，直接恢复</b><small>看一条关系与实际对照，之后换例。</small></button>`}<button data-action="keys-help"><b>找不到琴键 / 操作不方便</b><small>先解决位置与输入条件，不记为乐理失败。</small></button></div></section><aside class="panel side"><div class="eyebrow">你始终能决定</div><h2>诊断可以跳过</h2><p>想直接查答案，请选“直接查阅”；想找回记忆，可以先看短提示，再用另一份材料不看答案试一次。</p><div class="support-controls"><button class="secondary" data-action="direct-lookup">直接查阅</button><button class="primary" data-action="skip-diagnosis">跳过短测</button></div><div class="rulebox">${c['复习任务']}</div></aside></div>`}
function chooseQuestion(id,dimension,{familiar=false,stage='diagnosis',purpose='recover'}={}){id=practiceConcept(id);const options={quality:state.quality,pattern:id==='T03'?'bass-chord':id==='T02'?(state.pattern==='block'?'block':'broken'):state.pattern};if(id.startsWith('T'))state.pattern=options.pattern;let pool=U.pool(id,dimension,options);if(!pool.length){toast('本概念目前只提供查阅。');return}const unseen=journal.unseen(pool);if(!unseen.length&&!familiar){state.poolOptions={id,dimension,stage,purpose};state.page='pool';render();return}let choices=unseen.length?unseen:pool;const pick=choices.length>1?Math.floor(Math.random()*choices.length):0;const q=copy(choices[pick]);const existing=journal.data.reviews[id+':'+q.dimension];const novel=!TheoryData.seen(journal.data,q.signature),recent=journal.data.events.filter(e=>e.type==='exposure'&&e.signature===q.signature&&['lookup','feedback','answer','hint'].includes(e.reason)&&Date.now()-e.at<600000).pop();const now=Date.now();state.session={id:'session-'+now+'-'+Math.random().toString(36).slice(2,7),startedAt:now,conceptId:id,dimension:q.dimension,question:q,stage,purpose,phase:'question',hints:0,answerExposed:!!recent,lookupSeen:false,feedbackSeen:false,novelAtStart:novel,reviewBaseAt:existing?.lastAt||null,source:input.active,response:{notes:[],events:[],choice:null,spelledUpper:'',generic:'',semitones:''},heard:false,replays:0,submitted:false,result:null,returnTask:state.returnTask?copy(state.returnTask):null};state.conceptId=id;state.page='session';if(q.kind==='timeline')state.editorBar=innerWidth<650?'0':'all';journal.expose(q.signature,'presented',id,now);journal.event('session-start',{sessionId:state.session.id,conceptId:id,dimension:q.dimension,purpose,stage,novelAtStart:novel,priorImmediateExposure:!!recent});quiet();if(['chord','bass','voice'].includes(q.kind))state.keyboardStart=Math.min(72,Math.max(24,Math.floor(Math.min(...q.notes)/12)*12));if(q.kind==='interval'){state.session.response.notes=[q.notes[0]];input.latch=new Set([q.notes[0]]);state.keyboardStart=Math.min(72,Math.max(24,Math.floor(q.notes[0]/12)*12));}save();render()}
function skipDiagnosis(){state.demoId=null;const id=practiceConcept(state.conceptId);state.session={id:'support-'+Date.now(),conceptId:id,dimension:id==='I02'?'construction':id.startsWith('T')?'arrangement':id==='C06'?'voice':'construction',phase:'support',hints:0,returnTask:state.returnTask?copy(state.returnTask):null};journal.event('diagnosis-skipped',{conceptId:id});exposeMaterial(mainExample(id),'answer',id);state.page='session';save();render()}
function openSupport(){if(!state.session)return;quiet();state.demoId=null;state.session.phase='support';state.session.lookupSeen=true;state.session.answerExposed=true;journal.event('minimal-support',{conceptId:state.session.conceptId,dimension:state.session.dimension,error:state.session.result?.code||null});if(state.session.question)journal.expose(state.session.question.signature,'answer',state.session.conceptId);exposeMaterial(mainExample(state.session.conceptId),'answer',state.session.conceptId);save();render()}
function support(){const s=state.session,c=concept(s.conceptId),m=mainExample(c.id);let reason=s.result?.code==='name'?'先恢复名字与声音/谱写的对应，不重学已经会的构造。':s.result?.code==='bass'?'组成音已经对了，只恢复最低实际音与转位这一步。':s.dimension==='hearing'?'先保持同一起始音比较，再撤去谱与音名，听另一份材料。':c.id.startsWith('T')?'先分低声部与上方声部，再按四拍安排。会编排仍不等于双手演奏。':'一句关系，加一个可改变的例子。';return `<div class="head"><div><div class="eyebrow">最小恢复 · 不从整课重来</div><h1>${c.title}</h1><p>${reason}</p></div><span class="spacer"></span>${returnButton()}</div><div class="body-grid"><section class="panel"><div class="panel-head">这是辅助示例，接下来换材料再独立尝试</div><div class="score">${notation(m.events,{bars:m.bars,hideLabels:m.events.length>6})}</div><div class="subline">${c['控制变量对比']}</div><div class="support-controls" style="padding:0 14px 12px">${miniButtons(c.id)}</div></section><aside class="panel side"><h2>${c['为何命名/形成']}</h2><p>${c['复习任务']}</p><div class="rulebox">${s.dimension==='hearing'?'听觉比较后，下一份题会重新隐藏谱面和琴键，不靠看到的答案作答。':c.id.startsWith('T')?state.pattern==='block'?'每小节第1拍三音同时起奏，保持4拍。':state.pattern==='broken'?'每小节根→三→五→三，各1拍。':'低音保持四拍；上方在第2/4拍各1拍。':c['常见误区']}</div><p style="margin-top:12px">关闭提示不会抹去这份材料的曝光。下一步优先选应用里未展示过的平行材料。</p></aside></div><div class="actions"><p>读过、听过与独立取回分别记录。</p><button class="secondary" data-action="direct-lookup">再查详细解释</button><button class="primary" data-action="parallel">关闭提示，换例验证 →</button></div>`}
function poolPage(){return `<div class="head"><h1>这组未展示材料已用完</h1><span class="spacer"></span>${returnButton()}</div><div class="pool-exhausted"><h2>可以继续练熟悉材料</h2><p>不会换一个编号就把旧材料说成“未见迁移”。熟悉材料的无提示回忆仍有价值；是否独立、是否已见、实际间隔会分别记录。</p><button class="primary" data-action="familiar">用熟悉材料练一次</button><button class="secondary" data-action="direct-lookup">改为查阅</button></div>`}
function optionsQuestion(q,s){if(q.kind==='listen'||q.kind==='name')return `<div class="question-options">${[['major','大三度'],['minor','小三度'],...(q.kind==='name'?[['aug2','增二度']]:[])].map(([id,label])=>`<button data-answer="${id}" class="${s.response.choice===id?'active':''}">${label}</button>`).join('')}</div>`;if(q.kind==='explain')return `<div class="dual-input"><label>音名位置<select id="tl-generic"><option value="">请选择</option>${[2,3,4,5,6].map(n=>`<option value="${n}" ${+s.response.generic===n?'selected':''}>${n}个位置</option>`).join('')}</select></label><label>半音距离<select id="tl-semitones"><option value="">请选择</option>${[2,3,4,5,6,7].map(n=>`<option value="${n}" ${+s.response.semitones===n?'selected':''}>${n}个半音</option>`).join('')}</select></label></div>`;
 if(q.kind==='interval'){const upper=(s.response.notes||[]).filter(n=>n!==q.notes[0]).sort((a,b)=>a-b).at(-1),names=upper===undefined?[]:K.enharmonics(upper);return `<p>下音已给出：<b>${q.written[0]}</b>。选出完整两音，并为上音选择拼写。</p><label class="dual-input">上音谱写<select id="tl-written-upper"><option value="">先选上方琴键，再选音名</option>${names.map(n=>`<option value="${n}" ${s.response.spelledUpper===n?'selected':''}>${n}</option>`).join('')}</select></label>`}
 if(q.kind==='timeline')return '<p>选音格是“起音”，长音格显示延续。选择音长与角色后点格；再点同一起音可删除。先一小节，再接第二小节。</p>';
 return `<p>${q.kind==='bass'?'先构成和弦，再让指定音成为最低实际音。':q.kind==='voice'?'只构造两条声部的目标音；此任务不等于连续演奏。':'选出组成音；可用触屏或MIDI。构造按音级检查，演奏技能另行验证。'}</p>`}
function editor(events,q,{answerShown=false}={}){const selectedBar=state.editorBar==='all'?null:+state.editorBar,beats=selectedBar===null?Array.from({length:8},(_,i)=>i):Array.from({length:4},(_,i)=>selectedBar*4+i),rows=[...new Set(selectedBar===null?q.pitches.flat():q.pitches[selectedBar])].sort((a,b)=>b-a),labelMap={};q.pitches.flat().forEach((n,i)=>labelMap[n]=q.written[i]);return `<div class="grid-editor"><div class="event-grid" style="grid-template-columns:75px repeat(${beats.length},minmax(43px,1fr));min-width:${beats.length===4?300:449}px"><div class="beat-label">音名 / 角色</div>${beats.map(i=>`<div class="beat-label ${i===4?'bar2':''}">${Math.floor(i/4)+1}小节·${i%4+1}拍</div>`).join('')}${rows.map(n=>`<div class="row-label">${esc(labelMap[n]||C.note(n))}</div>${beats.map(beat=>{const onset=events.find(e=>e.midi===n&&e.onsetBeat===beat),continued=events.some(e=>e.midi===n&&e.onsetBeat<beat&&e.onsetBeat+e.durationBeats>beat);return `<button class="event-cell ${onset?'on':continued?'continue':''} ${beat===4?'bar2':''}" data-cell="${n}:${beat}" aria-label="${labelMap[n]||C.note(n)} 第${Math.floor(beat/4)+1}小节第${beat%4+1}拍">${onset?onset.durationBeats+'拍 · '+(onset.role==='bass'?'低':'上'):continued?'—':''}</button>`}).join('')}`).join('')}</div></div><div class="editor-controls"><label>视图<select id="tl-editor-bar"><option value="all" ${state.editorBar==='all'?'selected':''}>两小节</option><option value="0" ${state.editorBar==='0'?'selected':''}>第1小节</option><option value="1" ${state.editorBar==='1'?'selected':''}>第2小节</option></select></label><label>新音长度<select id="tl-event-duration">${[1,2,4].map(n=>`<option value="${n}" ${state.duration===n?'selected':''}>${n}拍</option>`).join('')}</select></label><label>新音角色<select id="tl-event-role"><option value="auto">按音区分角色</option><option value="bass" ${state.role==='bass'?'selected':''}>低声部</option><option value="upper" ${state.role==='upper'?'selected':''}>上方声部</option></select></label><button class="secondary" data-action="clear-events">清空编排</button><span class="event-count">${events.length}个起音</span></div><div class="key-legend">${q.labels.join(' → ')} · 每小节一个和声 · ${U.patternName(q.pattern)} · 编排证据，非双手演奏</div>`}
function questionPage(){const s=state.session,q=s.question,isEar=q.kind==='listen',isTimeline=q.kind==='timeline';const hideAnswer=q.kind==='interval'||q.kind==='chord'||q.kind==='bass'||q.kind==='voice';let displayNotes=hideAnswer?s.response.notes:q.notes;const body=isEar?`<div class="hidden-sound"><span class="sound-mark" aria-hidden="true">♫</span><p>谱面、音名与琴键高亮已隐藏。请听两音的关系，再选大三度或小三度。</p><button class="primary" data-action="listen-question">▶ ${s.heard?'再听一遍':'开始试听'}</button><div class="listen-state" data-listen-status></div></div>`:isTimeline?editor(s.response.events,q):`<div class="score">${notesScore(displayNotes,hideAnswer?[]:q.written,activeSpelling())}</div><div class="subline">${q.kind==='interval'?'给定下音 '+q.written[0]+'；检查真实音区与拼写。':q.kind==='voice'?q.sourceWritten.join('、')+' → 你的目标音（保留实际音区）':'按当前材料核对。音级构造与实际演奏分开。'}</div>`;
 return `<div class="head"><div><div class="eyebrow">${s.stage==='parallel'?'关闭提示后的平行验证':s.stage==='review'?'主动 / 到期回顾':'可跳过的短诊断'} · ${K.dimensions[s.dimension]}</div><h1>${isEar?'听一组声音，判断三度':q.title}</h1><p>${s.novelAtStart?'本应用此前未展示这份材料':'熟悉材料重做，不记未见迁移'}${s.reviewBaseAt?' · 距上次作答 '+duration(Date.now()-s.reviewBaseAt):''}</p></div><span class="spacer"></span>${returnButton()}</div><div class="body-grid ${isTimeline?'timeline-body':''}"><section class="panel"><div class="panel-head">${isEar?'声音是主要线索':isTimeline?'按实际拍位、音长与角色编排':'先不看答案，尝试重建'}</div>${body}</section><aside class="panel side"><h2>${isEar?'这次听到的是哪一种？':isTimeline?U.patternName(q.pattern):q.kind==='interval'?'级数与性质，两项都要对':'你的任务'}</h2>${optionsQuestion(q,s)}${s.hints?`<div class="hint">提示${s.hints}/3：${U.hints(q)[s.hints-1]}</div>`:''}${s.hints>=3&&isTimeline?'<p>目标已在“看目标编排”中展开，本题按辅助记录。</p>':''}${s.result?`<div class="feedback ${s.result.correct?'':'wrong'}"><strong>${s.result.correct?'这次符合目标':'先修正这一点'}</strong><p>${esc(s.result.reason)}</p><small>${s.lastAttempt?.assisted?'本次有提示/即时答案暴露，记辅助。':s.lastAttempt?.correct?'无当前辅助；材料是否已见与实际间隔另列。':''}</small></div>`:''}</aside></div><div class="actions"><p>声音/输入故障可先解决，不算乐理错误。</p>${s.stage==='diagnosis'?'<button class="secondary" data-action="session-skip">跳过短测</button>':''}<button class="secondary" data-action="hint">给一点提示</button>${isTimeline?'<button class="secondary" data-action="play-draft">▶ 听我的编排</button>':!isEar&&hideAnswer?'<button class="secondary" data-action="play-response">▶ 听我的输入</button>':''}<button class="primary" data-action="submit" ${s.submitted?'disabled':''}>检查这次尝试</button>${s.result?`<button class="secondary" data-action="${s.result.correct?'parallel':'support'}">${s.result.correct?'换例 / 再取回 →':'最小恢复 →'}</button>`:''}</div>`}
function taskMaterial(){if(state.task.kind==='texture')return U.textures(state.task.pattern)[0];return material(state.task.materialId)}
function taskPage(){const m=taskMaterial(),choices={interval:'音程小句',chord:'和弦小句',texture:'两小节伴奏'},ctx=state.task.kind==='interval'?'I02':state.task.kind==='chord'?'C01':state.task.pattern==='bass-chord'?'T03':'T02';return `<div class="head"><div><div class="eyebrow">实例内原任务 · 随时查阅 / 恢复再返回</div><h1>我的练习片段</h1><p>保留你的位置、速度、手别和输入；教学示例；生产曲谱使用顶部返回原段。</p></div><span class="spacer"></span><button class="secondary" data-action="task-recover">这里忘了</button><button class="primary" data-action="task-lookup">这里为什么？</button></div><div class="controls"><label>片段<select id="tl-task-kind">${Object.entries(choices).map(([k,label])=>`<option value="${k}" ${state.task.kind===k?'selected':''}>${label}</option>`).join('')}</select></label><label>速度<select id="tl-task-tempo">${[40,60,80,100].map(n=>`<option value="${n}" ${state.task.tempo===n?'selected':''}>♩ ${n}</option>`).join('')}</select></label><label>手别<select id="tl-task-hand">${[['both','双手/整体'],['left','左手'],['right','右手']].map(([id,label])=>`<option value="${id}" ${state.task.hand===id?'selected':''}>${label}</option>`).join('')}</select></label><label>位置<select id="tl-task-bar">${Array.from({length:m.bars},(_,i)=>`<option value="${i+1}" ${state.task.bar===i+1?'selected':''}>第${i+1}小节</option>`).join('')}</select></label><label>选段<select id="tl-task-range"><option value="all" ${state.task.range==='all'?'selected':''}>整段</option><option value="current" ${state.task.range==='current'?'selected':''}>当前小节</option></select></label></div><div class="body-grid"><section class="panel"><div class="panel-head">${choices[state.task.kind]} · ${state.task.cursor}<span class="spacer"></span>${m.meter[0]}/${m.meter[1]} · 实际拍位</div><div class="score">${notation(m.events,{bars:m.bars,hideLabels:m.events.length>6})}</div><div class="subline">${state.task.kind==='texture'?'固定C3/E4/G4、F3/A4/C5；每小节换一次和声。':state.task.kind==='chord'?'C4/E4/G4。可与Cm比较，改的是三音。':'C4先到E4；音程级数与半音性质分别理解。'}</div></section><aside class="panel side"><h2>${concept(ctx).title}</h2><p>${concept(ctx)['是什么']}</p><div class="rulebox">${concept(ctx)['为何命名/形成']}</div>${state.task.kind==='texture'?`<div class="support-controls">${['block','broken','bass-chord'].map(p=>`<button class="${state.task.pattern===p?'active':'secondary'}" data-task-pattern="${p}">${U.patternName(p)}</button>`).join('')}</div>`:''}<p style="margin-top:13px">选音/编排用于探索，点选不会被报告为双手演奏。位置与手别会在返回时恢复。</p></aside></div><div class="actions"><p id="tl-return-context">${state.task.cursor} · ♩${state.task.tempo} · ${state.task.hand==='both'?'整体':state.task.hand==='left'?'左手':'右手'}</p><button class="secondary" data-action="play-task">▶ 播放选段</button><button class="secondary" data-action="play-response">▶ 听当前选音</button><button class="primary" data-action="task-practice">围绕这里练一次 →</button></div>`}
function evidencePage(){const touched=[...new Set(journal.data.events.filter(e=>e.conceptId).map(e=>e.conceptId))],due=journal.due();return `<div class="head"><div><div class="eyebrow">真实时间 · 分维证据 · 本地保存</div><h1>想复习时，直接取回这一部分</h1><p>到期是建议，不代表已经忘了。无提示回忆、未见材料与延迟保留分开看。</p></div><span class="spacer"></span><button class="secondary" data-action="export">导出记录</button><button class="secondary danger" data-action="clear-records">清除</button></div><div class="notice">${journal.error||'记录保存在本机APP，基础练习备份包含乐理记录。'} 这里记录构造/编排证据，没有自动判定双手演奏能力；长期效果仍待实际使用验证。</div>${due.length?`<div class="pills">${due.map(r=>`<button class="secondary" data-review="${r.conceptId}:${r.dimension}">${concept(r.conceptId)?.title} · ${K.dimensions[r.dimension]}：建议回顾</button><button data-postpone="${r.conceptId}:${r.dimension}">明天再说</button>`).join('')}</div>`:'<small>目前没有到期项。仍可随时主动复习，不必等待系统安排。</small>'}<div class="scroll">${touched.map(id=>{const c=concept(id);if(!c)return '';return `<article class="evidence-card"><header><h3>${c.title}</h3><span class="spacer"></span><button class="secondary" data-recover="${id}">主动复习</button><button data-concept="${id}">查一下</button></header><div class="evidence-grid">${journal.evidence(id).map(e=>`<div class="evidence-unit"><b>${e.label}</b>${e.attempts?'独立 '+e.independent+' · 辅助 '+e.assisted+' · 未符 '+e.incorrect:'尚未获得作答证据'}${e.last?'<br>最近间隔：'+duration(e.last.actualIntervalMs)+'<br>'+(e.last.novelAtStart?'当时本应用未展示':'当时是熟悉材料')+(e.last.actualIntervalMs>=86400000?' · 已有实际跨日间隔':' · 不称隔日保留'):''}</div>`).join('')}</div></article>`}).join('')||'<div class="empty">尚无记录。直接查阅也会记曝光，但不会制造对错或独立成绩。</div>'}</div><div class="actions"><p>提示后当场成功与隔后无提示回忆不是同一条证据。</p><button class="primary" data-page="home">找一个想复习的概念 →</button></div>`}
function syncLatch(){if(input.active==='touch'&&input.mode==='latch'&&!input.held.size&&!input.latch.size&&actualNotes().length)input.latch=new Set(actualNotes())}
function render(){root.dataset.view=state.page;root.dataset.kind=state.session?.question?.kind||'';syncLatch();const main=state.page==='home'?home():state.page==='concept'?conceptPage():state.page==='routes'?routes():state.page==='pool'?poolPage():state.page==='task'?taskPage():state.page==='evidence'?evidencePage():state.session?.phase==='support'?support():questionPage();$('#tl-main').innerHTML=main;root.querySelectorAll('[data-page]').forEach(b=>b.classList.toggle('active',state.page===b.dataset.page));const needsKeys=state.page==='task'||(state.page==='session'&&state.session.phase==='question'&&['interval','chord','bass','voice'].includes(state.session.question.kind));$('#tl-dock').classList.toggle('hidden',!needsKeys);$('#tl-app').classList.toggle('keys-collapsed',state.keysHidden);$('#tl-app').classList.toggle('midi-source',input.active==='midi');$('#tl-hide-keys').textContent=state.keysHidden?'展开键盘 ↑':'收起键盘 ↓';$('#tl-source').value=input.active;$('#tl-touch-mode').value=input.mode;$('#tl-input-label').textContent='实际选音 · '+(input.mode==='latch'?'点选保留':'多指按住');if(needsKeys)renderKeys();renderPlaying();window.dispatchEvent(new Event('pianotheoryview'));}
function renderKeys(){const whites=[];for(let n=state.keyboardStart;n<state.keyboardStart+24;n++)if(![1,3,6,8,10].includes(n%12))whites.push(n);const sp=activeSpelling();let html=whites.map(n=>`<button class="white-key" data-note="${n}" aria-label="${esc(noteName(n,sp))}"><span>${esc(C.note(n,sp,n%12===0))}</span></button>`).join('');whites.forEach((n,i)=>{if([0,2,5,7,9].includes(n%12))html+=`<button class="black-key" style="left:calc(${(i+1)*100/whites.length}% - 2.05%)" data-note="${n+1}" aria-label="${esc(noteName(n+1,sp))}"></button>`});$('#tl-keys').innerHTML=html;updateKeys()}
function updateKeys(){const ns=actualNotes(),held=input.pitches();root.querySelectorAll('[data-note]').forEach(b=>{const n=+b.dataset.note;b.classList.toggle('selected',ns.includes(n));b.classList.toggle('held',held.includes(n));b.setAttribute('aria-pressed',ns.includes(n))})}
function setResponse(key,value){const s=state.session;if(!s)return;s.response[key]=value;s.result=null;s.submitted=false;save();render()}
function submit(){const s=state.session;if(!s?.question||s.submitted)return;const a={...s.response,heard:s.heard};const result=K.grade(s.question,a);if(result.record===false)return toast(result.reason);const recent=journal.data.events.filter(e=>e.type==='exposure'&&e.signature===s.question.signature&&['lookup','answer','feedback','hint'].includes(e.reason)&&Date.now()-e.at<600000).pop();if(recent)s.answerExposed=true;s.source=s.question.kind==='timeline'?'grid':s.question.kind==='listen'?'audio-choice':input.active;const attempt=journal.record(s,a,result);if(!attempt)return toast('这个答案已经记录过，换例或修改后再试。');s.lastAttempt=attempt;s.result=result;s.submitted=true;save();render()}
function hint(){const s=state.session;if(!s?.question)return;s.hints=Math.min(3,(s.hints||0)+1);journal.event('hint',{sessionId:s.id,conceptId:s.conceptId,materialId:s.question.id,level:s.hints,text:U.hints(s.question)[s.hints-1]});journal.expose(s.question.signature,s.hints>=3?'answer':'hint',s.conceptId);if(s.hints>=3){s.answerExposed=true;if(s.question.kind==='timeline')modal('目标编排（已揭示）',`<p>接下来完成按辅助记录。关闭面板不会清除曝光。</p><table><tr><th>音</th><th>起于</th><th>长度</th><th>角色</th></tr>${s.question.events.map(e=>`<tr><td>${C.note(e.midi)}</td><td>${Math.floor(e.onsetBeat/4)+1}小节${e.onsetBeat%4+1}拍</td><td>${e.durationBeats}拍</td><td>${e.role==='bass'?'低':'上'}</td></tr>`).join('')}</table>`)}save();render()}
async function listenQuestion(){const s=state.session;if(!s||s.question.kind!=='listen')return;const id=s.id;s.heard=false;s.replays++;journal.event('replay',{sessionId:id,conceptId:s.conceptId,materialId:s.question.id,count:s.replays});save();await play(LearnerPlayer.hearing(s.question.notes,s.question.presentation),{tempo:60,onDone:()=>{if(state.session?.id!==id)return;state.session.heard=true;journal.event('heard-complete',{sessionId:id,conceptId:s.conceptId});save();renderPlaying()}})}
function playDemo(id){const m=material(id);if(!m)return;state.demoId=id;render();markLookup(state.conceptId);return play(m,{tempo:60})}
function cellClick(value){const [midi,beat]=value.split(':').map(Number),s=state.session;if(!s||s.question.kind!=='timeline')return;const q=s.question;const i=s.response.events.findIndex(e=>e.midi===midi&&e.onsetBeat===beat);if(i>=0)s.response.events.splice(i,1);else{if(beat+state.duration>8)return toast('音符超过片段末尾，请缩短音长。');const bar=Math.floor(beat/4),bass=q.pitches[bar][0]===midi,role=state.role==='auto'?(bass?'bass':'upper'):state.role;s.response.events.push({midi,onsetBeat:beat,durationBeats:state.duration,role,voice:role,hand:role==='bass'?'left':'right',velocity:64})}s.result=null;s.submitted=false;save();render()}
function inputSearch(){return window.PianoTheory.openExplorer();const ns=state.task.notes;const matches=C.analyze(ns).matches;modal('从实际输入找知识',`<p>先在“我的练习片段”选音，再用这里找关系。当前：${ns.map(n=>C.note(n)).join(' · ')||'尚无输入'}。</p>${ns.length===2?`<p>两音相距${Math.abs(ns[1]-ns[0])}半音。仅凭键位不能确定唯一谱写，可进入音程检查。</p><button class="primary" data-concept="I02">看音程关系</button>`:matches.length?`<p>候选：${matches.map(c=>esc(c.name)).join(' / ')}。低音不证明根音，单和弦不确定整曲调。</p><button class="primary" data-concept="C01">查构成与命名</button><button class="secondary" data-concept="C02">查根音 / 低音</button><button class="secondary" data-concept="C07">看多义与证据</button>`:'<p>可先选两个音或一组三和弦；静态音组不能确定伴奏时间组织。</p><button class="primary" data-page="task">去片段选音</button>'}`)}
function connectMidi(){window.PianoInput?.open();}

function about(){modal('乐理与和弦',`<p>18概念可直接查阅；音程、基础和弦、转位、声部目标与三种织体有实践任务。构造、听辨和拍格编排分开记录，不代表指法或双手演奏合格。</p><p>和弦探索保留精确与条件候选、调性背景、动态续接、实际配音和短链条编辑。单个音组不能决定整曲调性。</p><p>原曲帮助返回保存曲目、片段、手别、速度和位置，保持暂停；使用帮助的训练保留辅助记录。基础备份包含乐理，曲谱库需单独备份。</p><p>实体琴使用统一USB MIDI输入；此版本不使用麦克风识别。采样：Salamander Grand Piano，Alexander Holm，CC BY 3.0，许可随应用提供。</p><p>曝光摘要在裁切后可能保守判为已见／辅助；间隔建议与实际学习效果仍需使用验证。</p>`)}
root.addEventListener('click',e=>{const b=e.target.closest('button');if(!b||b.disabled)return;if(b.dataset.page){closeModal();return b.dataset.page==='task'?window.PianoHost.showPage('songsPage'):changePage(b.dataset.page)}if(b.dataset.concept){closeModal();return openConcept(b.dataset.concept)}if(b.dataset.recover){state.conceptId=b.dataset.recover;return openConcept(b.dataset.recover,'recover')}if(b.dataset.category){state.category=b.dataset.category;return render()}if(b.dataset.route){quiet();return chooseQuestion(state.conceptId,b.dataset.route)}if(b.dataset.answer)return setResponse('choice',b.dataset.answer);if(b.dataset.cell)return cellClick(b.dataset.cell);if(b.dataset.demo)return playDemo(b.dataset.demo);if(b.dataset.pattern){stop();state.pattern=b.dataset.pattern;state.conceptId=b.dataset.pattern==='bass-chord'?'T03':'T02';if(state.session)state.session.conceptId=state.conceptId;markLookup(state.conceptId);render();return play(U.textures(state.pattern)[0],{tempo:60})}if(b.dataset.taskPattern){stop();state.task.pattern=b.dataset.taskPattern;exposeMaterial(taskMaterial(),'lookup',state.task.pattern==='bass-chord'?'T03':'T02');save();return render()}if(b.dataset.review){const [id,dim]=b.dataset.review.split(':');state.returnTask=null;return chooseQuestion(id,dim,{stage:'review',purpose:'review'})}if(b.dataset.postpone){journal.postpone(b.dataset.postpone);return render()}
const a=b.dataset.action;if(!a)return;
if(a==='open-explorer')return window.PianoTheory.openExplorer();if(a==='forgot'){state.page='routes';state.conceptId='I02';return render()}if(a==='return')return restoreTask();if(a==='recover'){state.page='routes';return render()}if(a==='direct-lookup'){if(state.session)state.session.lookupSeen=true;return openConcept(state.conceptId)}if(a==='skip-diagnosis'||a==='session-skip')return skipDiagnosis();if(a==='practice'){const id=practiceConcept(state.conceptId),dim=id==='I02'?'construction':id.startsWith('T')?'arrangement':id==='C06'?'voice':'construction';return chooseQuestion(id,dim,{purpose:'practice'})}if(a==='parallel'){const s=state.session;quiet();return chooseQuestion(s.conceptId,s.dimension,{stage:'parallel',purpose:'retrieve'})}if(a==='familiar'){const o=state.poolOptions;return chooseQuestion(o.id,o.dimension,{...o,familiar:true})}if(a==='hint')return hint();if(a==='submit')return submit();if(a==='support')return openSupport();if(a==='listen-question')return listenQuestion();if(a==='keys-help'){if(state.session){state.session.lookupSeen=true;save()}journal.event('input-help',{conceptId:state.conceptId});return modal('先找到键，不记乐理失败','<p>每组两个黑键的左侧白键是C，三个黑键左侧白键是F。琴键下方显示音名；中央C为C4。</p><p>点选模式可逐个保留，多指模式必须按住；也可清空重选。请先解决位置与设备问题，再判断关系。</p><button class="secondary" data-page="task">去片段找键</button>')}
if(a==='play-lookup-example'){markLookup(state.conceptId);return play(mainExample(state.conceptId),{tempo:60})}if(a==='lookup-variant'){stop();state.lookupVariant=!state.lookupVariant;state.demoId=null;markLookup(state.conceptId);return render()}if(a==='play-response')return play(sequenceFromNotes(actualNotes()),{tempo:60});if(a==='play-draft'){const q=state.session.question;return play({...q,events:state.session.response.events},{tempo:60})}if(a==='clear-events'){state.session.response.events=[];state.session.result=null;state.session.submitted=false;save();return render()}if(a==='mini-change'){state.miniMinor=!state.miniMinor;return playDemo(state.miniMinor?'B-Minor':'B-Major')}if(a==='flow-upper'){markLookup('C06');const m=material('B-Flow');m.events=m.events.filter(e=>e.voice==='v3'||e.voice==='v4');return play(m,{tempo:60})}if(a==='play-task'){const m=taskMaterial(),start=state.task.range==='current'?(state.task.bar-1)*4:0,end=state.task.range==='current'?state.task.bar*4:m.bars*4;return play(m,{tempo:state.task.tempo,hand:state.task.hand,fromBeat:start,toBeat:end})}if(a==='task-lookup'||a==='task-recover'||a==='task-practice'){const id=state.task.kind==='interval'?'I02':state.task.kind==='chord'?'C01':state.task.pattern==='bass-chord'?'T03':'T02';state.returnTask=copy(state.task);if(a==='task-practice'){state.conceptId=id;return chooseQuestion(id,id.startsWith('T')?'arrangement':'construction',{purpose:'practice'})}return openConcept(id,a==='task-recover'?'recover':'lookup')}
if(a==='input-search')return inputSearch();if(a==='clear-records')return modal('只清除乐理学习记录','<p>清除乐理学习日志、曝光和复习；识谱、曲谱库与和弦探索链条保留。</p><button class="secondary danger" data-action="confirm-clear">确认清除乐理学习记录</button>');if(a==='confirm-clear'){quiet();journal.clear();state.session=null;state.returnTask=null;state.task=copy(defaultTask);state.page='home';closeModal();return render()}if(a==='export'){if(window.PianoAndroid){window.PianoAndroid.exportData('识谱与乐理备份.json',JSON.stringify(PianoHost.getDB()));return;}const blob=new Blob([JSON.stringify(journal.data,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='乐理学习记录.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
});
root.addEventListener('change',e=>{const id=e.target.id.replace(/^tl-/,''),v=e.target.value;if(id==='recover-topic'){state.conceptId=v;state.demoId=null;state.pattern=v==='T03'?'bass-chord':v==='T02'?'broken':state.pattern;save();return render()}if(id==='quality'){state.quality=v;return render()}if(id==='generic'||id==='semitones')return setResponse(id,v);if(id==='written-upper')return setResponse('spelledUpper',v);if(id==='editor-bar'){state.editorBar=v;return render()}if(id==='event-duration'){state.duration=+v;return}if(id==='event-role'){state.role=v;return}if(id==='task-kind'){stop();state.task.kind=v;state.task.materialId=v==='interval'?'A-Major-Melodic':'B-Major';state.task.bar=1;state.task.cursor='第1小节第1拍';exposeMaterial(taskMaterial(),'lookup',state.task.kind==='interval'?'I02':state.task.kind==='chord'?'C01':'T02');save();return render()}if(id==='task-tempo'){stop();state.task.tempo=+v;save();return render()}if(id==='task-hand'){stop();state.task.hand=v;save();return render()}if(id==='task-bar'){state.task.bar=+v;state.task.cursor='第'+v+'小节第1拍';save();return render()}if(id==='task-range'){state.task.range=v;save();return}if(id==='source'){release();input.setActive(v);if(v==='midi'&&!midiPorts.size)toast('尚未连接MIDI，可先使用触屏。');return render()}if(id==='touch-mode'){release();input.setMode(v);render()}});
root.addEventListener('input',e=>{if(e.target.id.replace(/^tl-/,'')!=='search')return;state.query=e.target.value;clearTimeout(debounceSearch);debounceSearch=setTimeout(()=>{const pos=e.target.selectionStart;render();$('#tl-search')?.focus();$('#tl-search')?.setSelectionRange(pos,pos)},160)});
$('#tl-stop').onclick=()=>{quiet();toast('已停止声音与待处理输入。')};$('#tl-midi').onclick=connectMidi;$('#tl-about').onclick=about;$('#tl-close-dialog').onclick=closeModal;$('#tl-dialog').addEventListener('close',()=>{syncLatch();updateKeys()});$('#tl-hide-keys').onclick=()=>{state.keysHidden=!state.keysHidden;render()};$('#tl-lower').onclick=()=>{release();state.keyboardStart=Math.max(24,state.keyboardStart-12);renderKeys()};$('#tl-higher').onclick=()=>{release();state.keyboardStart=Math.min(72,state.keyboardStart+12);renderKeys()};$('#tl-clear-notes').onclick=()=>{release();input.setDisplayed([])};
$('#tl-keys').addEventListener('pointerdown',e=>{const b=e.target.closest('[data-note]');if(!b||input.active!=='touch')return;e.preventDefault();const n=+b.dataset.note;if(input.mode==='latch')input.toggle(n);else{const port='touch/'+e.pointerId;pointerMap.set(e.pointerId,{port,n});try{$('#tl-keys').setPointerCapture(e.pointerId)}catch(err){}input.on(port,0,n)}});
function releasePointer(e,cancel){const p=pointerMap.get(e.pointerId);if(!p)return;pointerMap.delete(e.pointerId);cancel?input.reset(p.port):input.off(p.port,0,p.n)}$('#tl-keys').addEventListener('pointerup',e=>releasePointer(e,false));$('#tl-keys').addEventListener('pointercancel',e=>releasePointer(e,true));$('#tl-keys').addEventListener('lostpointercapture',e=>releasePointer(e,true));$('#tl-keys').addEventListener('keydown',e=>{if(![' ','Enter'].includes(e.key)||e.repeat)return;const b=e.target.closest('[data-note]');if(!b)return;e.preventDefault();input.toggle(+b.dataset.note)});
window.addEventListener('blur',quiet);window.addEventListener('pagehide',quiet);root.addEventListener('visibilitychange',()=>{if(document.hidden)quiet()});window.addEventListener('resize',()=>{clearTimeout(layoutTimer);layoutTimer=setTimeout(render,90)});
window.PianoTheoryLearner={state,journal,input,player,render,changePage,openConcept,chooseQuestion,skipDiagnosis,openSupport,submit,hint,restoreTask,play,quiet,listenQuestion,taskMaterial,activeQuestion,connectMidi,setResponse,cellClick};
if(actualNotes().length)state.keyboardStart=Math.min(72,Math.max(24,Math.floor(Math.min(...actualNotes())/12)*12));if(state.page==='task')exposeMaterial(taskMaterial(),'lookup',state.task.kind==='interval'?'I02':state.task.kind==='chord'?'C01':'T02');render();

Object.assign(window.PianoTheoryLearner,{root,pause(){quiet();},setNativeSource(source){if(input.active!==source){quiet();input.setActive(source);render();}},toggleKeys(){state.keysHidden=!state.keysHidden;render();},reload(){journal.data=TheoryData.learner(PianoHost.getDB().theory.learner);state.session=null;state.page='home';render();}});
})();
